    #[test]
    fn test_build_upsert_sql() {
        let kv_upsert = build_upsert_sql("kv", &["scope", "key", "value"]);
        assert_eq!(
            kv_upsert,
            "INSERT INTO \"kv\" (\"scope\", \"key\", \"value\") VALUES ($1, $2, $3) ON CONFLICT (\"scope\", \"key\") DO UPDATE SET \"value\" = EXCLUDED.\"value\""
        );

        let kv_conflict_only = build_upsert_sql("kv", &["scope", "key"]);
        assert_eq!(
            kv_conflict_only,
            "INSERT INTO \"kv\" (\"scope\", \"key\") VALUES ($1, $2) ON CONFLICT (\"scope\", \"key\") DO NOTHING"
        );

        let pc_upsert = build_upsert_sql("providerConnections", &["id", "provider", "name"]);
        assert_eq!(
            pc_upsert,
            "INSERT INTO \"providerConnections\" (\"id\", \"provider\", \"name\") VALUES ($1, $2, $3) ON CONFLICT (\"id\") DO UPDATE SET \"provider\" = EXCLUDED.\"provider\", \"name\" = EXCLUDED.\"name\""
        );
    }

