    #[test]
    fn test_pg_config_effective_url() {
        let base_url = "postgres://user:pass@localhost:5432/routerdb?sslmode=require";
        let effective = PgConfig::compute_effective_connection_string(base_url, Some("nr_abc12345"));
        assert!(effective.contains("options=-c+search_path%3Dnr_abc12345") || effective.contains("options=-c%20search_path%3Dnr_abc12345"));
        assert!(effective.contains("sslmode=require"));

        // No schema -> unchanged
        assert_eq!(PgConfig::compute_effective_connection_string(base_url, None), base_url);

        let cfg = PgConfig::new(base_url, Some("/test/dir"), false, Some(10)).unwrap();
        assert_eq!(cfg.max_connections, 10);
        assert!(cfg.schema.is_some());
        assert!(!cfg.force_ssl);
    }

    #[test]
    fn test_translate_sqlite_to_postgres() {
        let q1 = "SELECT * FROM providerConnections WHERE provider = ? AND isActive = ?";
        let t1 = translate_sqlite_to_postgres(q1);
        assert_eq!(
            t1,
            "SELECT * FROM \"providerConnections\" WHERE provider = $1 AND isActive = $2"
        );

        // String literals containing question marks should not be converted
        let q2 = "SELECT * FROM apiKeys WHERE name = 'question?mark' AND id = ?";
        let t2 = translate_sqlite_to_postgres(q2);
        assert_eq!(
            t2,
            "SELECT * FROM \"apiKeys\" WHERE name = 'question?mark' AND id = $1"
        );

        // datetime('now') translation
        let q3 = "INSERT INTO usageHistory (timestamp) VALUES (datetime('now'))";
        let t3 = translate_sqlite_to_postgres(q3);
        assert!(t3.contains("CURRENT_TIMESTAMP"));

        // INSERT OR IGNORE translation
        let q4 = "INSERT OR IGNORE INTO kv (scope, key, value) VALUES (?, ?, ?)";
        let t4 = translate_sqlite_to_postgres(q4);
        assert!(t4.contains("INSERT INTO"));
        assert!(t4.contains("ON CONFLICT DO NOTHING"));
    }

    #[test]
    fn test_memory_adapter_critical_and_lazy_tables() {
        assert!(PgMemoryAdapter::is_critical_table("settings"));
        assert!(PgMemoryAdapter::is_critical_table("apiKeys"));
        assert!(PgMemoryAdapter::is_critical_table("providerConnections"));
        assert!(!PgMemoryAdapter::is_critical_table("usageHistory"));
        assert!(!PgMemoryAdapter::is_critical_table("requestDetails"));

        assert!(PgMemoryAdapter::is_lazy_table("kv"));
        assert!(PgMemoryAdapter::is_lazy_table("usageHistory"));
        assert!(!PgMemoryAdapter::is_lazy_table("settings"));

        let config = PgConfig::new("postgres://localhost:5432/test", None, false, None).unwrap();
        let adapter = PgMemoryAdapter::new(config);
        assert!(!adapter.is_loaded("kv"));
        adapter.mark_loaded("kv");
        assert!(adapter.is_loaded("kv"));
        assert!(adapter.is_loaded("settings"));
    }

    #[test]
    fn test_memory_adapter_operations_and_flush_queue() {
        let config = PgConfig::new("postgres://localhost:5432/test", None, false, None).unwrap();
        let adapter = PgMemoryAdapter::new(config);

        // Insert into critical table -> triggers immediate flush requirement
        let mut key_row = HashMap::new();
        key_row.insert("id".to_string(), json!("key-123"));
        key_row.insert("key".to_string(), json!("sk-secret-token"));
        key_row.insert("name".to_string(), json!("Test Key"));

        let should_flush = adapter.insert_row("apiKeys", key_row).unwrap();
        assert!(should_flush, "Critical table must signal immediate flush");
        assert_eq!(adapter.queue_len(), 1);

        // Read back from in-memory tier
        let fetched = adapter.get_row("apiKeys", &[("id", &json!("key-123"))]);
        assert!(fetched.is_some());
        assert_eq!(fetched.unwrap().get("key").unwrap(), "sk-secret-token");

        // Insert into high-volume non-critical table -> should not trigger immediate flush
        let mut usage_row = HashMap::new();
        usage_row.insert("id".to_string(), json!(101));
        usage_row.insert("timestamp".to_string(), json!("2026-11-24T00:00:00Z"));
        usage_row.insert("model".to_string(), json!("gpt-4o"));

        let flush_usage = adapter.insert_row("usageHistory", usage_row).unwrap();
        assert!(!flush_usage, "Non-critical table should batch writes");
        assert_eq!(adapter.queue_len(), 2);

        // Drain queue for persistence
        let batch = adapter.drain_queue();
        assert_eq!(batch.len(), 2);
        assert_eq!(adapter.queue_len(), 0);

        // Generate batch SQL
        let sql_batch = adapter.generate_batch_sql(&batch);
        assert_eq!(sql_batch.len(), 2);

        // Delete row
        let mut del_key = HashMap::new();
        del_key.insert("id".to_string(), json!("key-123"));
        adapter.delete_row("apiKeys", del_key).unwrap();
        assert_eq!(adapter.queue_len(), 1);
        assert!(adapter.get_row("apiKeys", &[("id", &json!("key-123"))]).is_none());
    }

    #[test]
    fn test_deterministic_vs_transient_errors() {
        assert!(PgMemoryAdapter::is_deterministic_error("ERROR: duplicate key value violates unique constraint"));
        assert!(PgMemoryAdapter::is_deterministic_error("ERROR: null value in column \"provider\" violates not-null constraint"));
        assert!(PgMemoryAdapter::is_deterministic_error("ERROR: invalid input syntax for type integer: \"abc\""));
        assert!(!PgMemoryAdapter::is_deterministic_error("connection reset by peer"));
        assert!(!PgMemoryAdapter::is_deterministic_error("could not connect to server: Connection refused"));
    }

    #[test]
    fn test_connection_manager_stats() {
        let config = PgConfig::new("postgres://localhost:5432/test", None, false, None).unwrap();
        let mgr = PgConnectionManager::new(config);
        assert_eq!(mgr.health_check_sql(), "SELECT 1");

        mgr.record_query_success();
        mgr.record_query_success();
        mgr.record_query_failure();

        let (total, failed) = mgr.stats();
        assert_eq!(total, 3);
        assert_eq!(failed, 1);

        // Connection pool slots
        assert_eq!(mgr.active_connections(), 0);
        assert!(mgr.acquire_connection());
        assert_eq!(mgr.active_connections(), 1);
        mgr.release_connection();
        assert_eq!(mgr.active_connections(), 0);
    }

    #[test]
    fn test_pg_memory_indexed_lookups() {
        let config = PgConfig::new("postgres://localhost:5432/test", None, false, None).unwrap();
        let adapter = PgMemoryAdapter::new(config);

        for i in 0..100 {
            let mut row = HashMap::new();
            row.insert("id".to_string(), json!(format!("key-{}", i)));
            row.insert("key".to_string(), json!(format!("sk-test-{}", i)));
            row.insert("name".to_string(), json!(format!("Test Key {}", i)));
            adapter.insert_row("apiKeys", row).unwrap();
        }

        // Test O(1) PK index lookup
        let row_pk = adapter.get_row_by_pk("apiKeys", "key-42");
        assert!(row_pk.is_some());
        assert_eq!(row_pk.unwrap().get("key").unwrap(), "sk-test-42");

        // Test O(1) secondary API key index lookup
        let row_key = adapter.get_api_key_by_key("sk-test-88");
        assert!(row_key.is_some());
        assert_eq!(row_key.unwrap().get("id").unwrap(), "key-88");

        // Verify non-existent key returns None
        assert!(adapter.get_api_key_by_key("non-existent").is_none());
    }
